import { BrowserRouter as Router, Routes, Route } from "react-router-dom";

import Login from "./pages/login";
import Homepage from "./pages/homepage";
import Mybooking from "./pages/Mybooking";
import Review from "./pages/review";

import AdminLayout from "./pages/admin/admin_layout";

function AdminStartPage() {
  return (
    <section>
      <h2>ยินดีต้อนรับสู่ระบบจัดการ Booking CSTU</h2>
      <p>
        เลือกเมนูจากแถบด้านซ้ายเพื่อจัดการห้องประชุม
        รายการจอง ผู้ใช้งาน และรายงาน
      </p>
    </section>
  );
}

function App() {
  return (
    <Router>
      <Routes>
        {/* User pages */}
        <Route path="/" element={<Login />} />
        <Route path="/homepage" element={<Homepage />} />
        <Route path="/homepage.html" element={<Homepage />} />
        <Route path="/mybooking" element={<Mybooking />} />
        <Route path="/Mybooking.html" element={<Mybooking />} />
        <Route path="/review" element={<Review />} />

        {/* Admin layout */}
        <Route path="/admin" element={<AdminLayout />}>
          <Route index element={<AdminStartPage />} />
        </Route>
      </Routes>
    </Router>
  );
}

export default App;
